/**
 * Generates one Next.js app per area subdomain: apps/<id>/ for every site in
 * @rovqix/areas (plumber-websites, dental-practice-websites, …).
 *
 *   npm run create:area-apps
 *
 * Each app is a thin shell — config plus one-line route files — around the
 * shared pages in packages/area-site, so the 100 apps stay in sync. Re-run it
 * after adding a business type; it rewrites the generated files and removes
 * apps for sites that no longer exist.
 */
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const typeList = readFileSync("packages/areas/src/service-type-list.ts", "utf8");
const indexSrc = readFileSync("packages/areas/src/index.ts", "utf8");
const without = new Set([...indexSrc.match(/WITHOUT_SITE = new Set\(\[([^\]]*)\]/)[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]));
const ids = [...typeList.matchAll(/from "\.\.\/types\/([a-z-]+)"/g)].map((m) => m[1]).filter((t) => !without.has(t)).map((t) => `${t}-websites`);

const rootPkg = JSON.parse(readFileSync("apps/web/package.json", "utf8"));
const v = (name) => rootPkg.dependencies[name] ?? rootPkg.devDependencies[name];
const ASSETS = "packages/area-site/assets";
const R = "@rovqix/area-site/routes";

const files = (id) => ({
  "package.json": JSON.stringify(
    {
      name: `@rovqix/${id}`,
      version: "0.1.0",
      private: true,
      description: `${id}.rovqix.in — generated by scripts/create-area-apps.mjs`,
      scripts: {
        dev: "next dev",
        build: "next build",
        postbuild: "node ../../packages/area-site/scripts/strip-client-payloads.mjs out && node ../../scripts/check-export-size.mjs out",
        typecheck: "tsc --noEmit",
      },
      dependencies: {
        "@rovqix/area-site": "*",
        "@rovqix/areas": "*",
        "@rovqix/shared": "*",
        next: v("next"),
        react: v("react"),
        "react-dom": v("react-dom"),
      },
      devDependencies: {
        "@rovqix/typescript-config": "*",
        "@tailwindcss/postcss": v("@tailwindcss/postcss"),
        "@types/node": v("@types/node"),
        "@types/react": v("@types/react"),
        "@types/react-dom": v("@types/react-dom"),
        tailwindcss: v("tailwindcss"),
        typescript: v("typescript"),
      },
    },
    null,
    2
  ) + "\n",
  "next.config.mjs": `import { createAreaSiteConfig } from "@rovqix/area-site/next-config.mjs";\n\nexport default createAreaSiteConfig("${id}");\n`,
  "tsconfig.json": readFileSync("apps/web/tsconfig.json", "utf8"),
  "app/layout.tsx": `export { default, metadata } from "${R}/layout";\n`,
  "app/page.tsx": `export { default, metadata } from "${R}/home-page";\n`,
  "app/not-found.tsx": `export { default } from "${R}/not-found";\n`,
  "app/[slug]/page.tsx": `export const dynamicParams = false;\n\nexport { default, generateMetadata, generateStaticParams } from "${R}/area-page";\n`,
  "app/service/[track]/page.tsx": `export const dynamicParams = false;\n\nexport { default, generateMetadata, generateStaticParams } from "${R}/track-page";\n`,
  "app/robots.ts": `export const dynamic = "force-static";\n\nexport { default } from "${R}/robots";\n`,
  "app/sitemap.xml/route.ts": `export const dynamic = "force-static";\n\nexport { GET } from "${R}/sitemap";\n`,
});

for (const dir of readdirSync("apps")) {
  if (dir.endsWith("-websites") && !ids.includes(dir)) rmSync(join("apps", dir), { recursive: true, force: true });
}
for (const id of ids) {
  const root = join("apps", id);
  for (const [path, content] of Object.entries(files(id))) {
    mkdirSync(join(root, path, ".."), { recursive: true });
    writeFileSync(join(root, path), content);
  }
  cpSync(join(ASSETS, "app"), join(root, "app"), { recursive: true });
  cpSync(join(ASSETS, "public"), join(root, "public"), { recursive: true });
  cpSync(join(ASSETS, "postcss.config.mjs"), join(root, "postcss.config.mjs"));
}
console.log(`${ids.length} area apps in apps/ (${ids[0]} … ${ids[ids.length - 1]})`);
if (!existsSync("node_modules/@rovqix/" + ids[0])) console.log("Run npm install to link new apps.");
